public static List<String> permutations(String s) {
    List<String> result = new ArrayList<>();
    if (s.length() <= 1) {
        result.add(s);
        return result;
    }
    for (int i = 0; i < s.length(); i++) {
        char first = s.charAt(i);
        String rest = s.substring(0, i) + s.substring(i + 1);
        for (String p : permutations(rest)) {
            result.add(first + p);
        }
    }
    return result;
}

